import numpy as np
from search_blocks import canonical
for m in [1,2,3,5,8]:
 print('m=',m)
 for d in [1e-8,1e-4,1.,1e4,1e8]:
  heights=[-3.,-2.,-1.,d+1.,d+2.]
  blocks=canonical(m,1.,2.,d,heights)
  out=[np.linalg.slogdet(C.astype(np.float64)) for C in blocks]
  print(' d=',d,' signs=',[int(p.sign) for p in out], 'min log equilibrated determinant=',round(min(p.logabsdet for p in out),6))
print('Intermediate-height scan')
for m in [1,2,3,5,8]:
 minimum=float('inf'); allpos=True
 for d in np.geomspace(1e-8,1e8,161):
  for C in canonical(m,1.,2.,d,[-3.,-2.,-1.,d+1.,d+2.]):
   sign,logdet=np.linalg.slogdet(C.astype(np.float64));allpos=allpos and sign>0; minimum=min(minimum,logdet)
 print(m,allpos,minimum)

